import{describe,it,expect,beforeAll}from"vitest";import{readFileSync}from"node:fs";import{resolve,dirname}from"node:path";import{fileURLToPath}from"node:url";const __dirname=dirname(fileURLToPath(import.meta.url));function readExplorerFile(t){return readFileSync(resolve(__dirname,"../../batukeshwar-dutt-explorer",t),"utf-8")}function readHubData(){return readFileSync(resolve(__dirname,"../../freedom-fighters-hub/script.js"),"utf-8")}describe("Batukeshwar Dutt Explorer — Page Structure",()=>{let t;beforeAll(()=>{t=readExplorerFile("index.html")}),it("contains a hero section with page title and kicker",()=>{expect(t).toContain('class="bdutt-hero"'),expect(t).toContain("<h1>"),expect(t).toContain("Batukeshwar"),expect(t).toContain("Dutt"),expect(t).toContain("Long Live Revolution")}),it("contains all required content sections from the issue",()=>{["biography","timeline","assembly-bombing","imprisonment","legacy","references"].forEach(e=>{expect(t).toContain(`id="${e}"`),expect(t).toContain(`data-tab="${e}"`)})}),it("highlights his partnership with Bhagat Singh and the Assembly bombing",()=>{expect(t).toContain("Bhagat Singh"),expect(t).toContain("Central Legislative Assembly"),expect(t).toContain("8 April 1929"),expect(t).toContain("HSRA"),expect(t).toContain("Inquilab Zindabad")}),it("has a semantic heading hierarchy (single h1, multiple h2s)",()=>{const e=(t.match(/<h1[\s>]/g)||[]).length,a=(t.match(/<h2[\s>]/g)||[]).length;expect(e).toBe(1),expect(a).toBeGreaterThanOrEqual(6)}),it("uses HTTPS image sources with alt attributes",()=>{const e=t.match(/<img [^>]*>/g)||[];expect(e.length).toBeGreaterThanOrEqual(4),e.forEach(t=>{expect(t).toMatch(/src="https:\/\//),expect(t).toMatch(/alt="/),expect(t).not.toMatch(/src="http:\/\//)})}),it("links the shared stylesheet, page stylesheet, and script",()=>{expect(t).toContain('href="../../styles.css"'),expect(t).toContain('href="style.css"'),expect(t).toContain('src="script.js"')}),it("references authentic source documentation in References",()=>{expect(t).toContain("wikipedia.org"),expect(t).toContain("britannica.com"),expect(t).toContain("amritmahotsav.nic.in")})}),describe("Batukeshwar Dutt Explorer — Assets",()=>{it("includes a non-empty stylesheet themed for the revolutionary era",()=>{const t=readExplorerFile("style.css");expect(t.length).toBeGreaterThan(1e3),expect(t).toContain("bdutt-hero")}),it("includes a valid interactive script with required functions",()=>{const t=readExplorerFile("script.js");expect(t).toContain("activateTab"),expect(t).toContain("initTabNavigation"),expect(t).toContain("initThemeToggle"),expect(t).toContain("document.addEventListener('DOMContentLoaded'")})}),describe("Batukeshwar Dutt — Landing Page Integration",()=>{it("is listed as a card on the Freedom Fighters Hub landing page",()=>{const t=readHubData();expect(t).toContain("batukeshwar-dutt"),expect(t).toContain("Batukeshwar Dutt")}),it("includes the revolutionary-era metadata and a dedicated explorer link",()=>{const t=readHubData();expect(t).toContain("Partner of Bhagat Singh"),expect(t).toContain("Revolutionary"),expect(t).toContain("Central Legislative Assembly Bombing (1929)"),expect(t).toContain("../batukeshwar-dutt-explorer/index.html")})});